INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'bait-al-khair-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Bait Al-Khair in Muharraq.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من بيت الخير في Muharraq.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Registered community foundation funding university scholarships, vocational micro-grants, and neighborhood sustainability programs. Focusing on Annual University Scholarship Grant, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مؤسسة مجتمعية مسجلة تدعم المنح الجامعية ومشاريع التمكين المهني والاستدامة المحلية. من خلال خدمة منحة دراسية جامعية سنوية نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Registered community foundation funding university scholarships, vocational micro-grants, and neighborhood sustainability programs.</p><p>Focusing on <strong>Annual University Scholarship Grant</strong>, our Muharraq specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مؤسسة مجتمعية مسجلة تدعم المنح الجامعية ومشاريع التمكين المهني والاستدامة المحلية.</p><p>من خلال خدمة <strong>منحة دراسية جامعية سنوية</strong>، يعمل فريقنا في Muharraq على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Bait Al-Khair', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | بيت الخير', 'Executive guide by Bait Al-Khair covering Annual University Scholarship Grant benchmarks in Bahrain.', 'دليل تنفيذي من بيت الخير حول معايير منحة دراسية جامعية سنوية في البحرين.', 'Sustainability', '{"nonprofit","sustainability","Muharraq","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
